def transform(grid):
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    fg = next(v for v in counts if v != bg)
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Fill small collinear breaks of up to four cells with bridge color 2.
    for r in range(h):
        ps = [c for c, v in enumerate(grid[r]) if v == fg]
        for a, b in zip(ps, ps[1:]):
            if b-a <= 5:
                for c in range(a+1,b):
                    if grid[r][c] == bg: out[r][c] = 2
    for c in range(w):
        ps = [r for r in range(h) if grid[r][c] == fg]
        for a, b in zip(ps, ps[1:]):
            if b-a <= 5:
                for r in range(a+1,b):
                    if grid[r][c] == bg: out[r][c] = 2
    return out

